VALUES
('domain', 'D078', 'D078', 'skill', 'd078-research-question-design', 'Frame a researchable social question and choose a fitting design', 'Research design is the plan connecting a question to information and methods that could answer it. For example, asking whether access to a bus route affects students’ attendance means deciding what attendance and access evidence would show before choosing how to collect it.', 'Use this when turning a social issue into a question that can be investigated, then deciding what information and method could answer it.', 'A short question, evidence plan and reasoned method choice; example is illustrative, not a prescribed study.', 'build_next', 'A useful shared starting point when the learner chooses a research route; not a prerequisite for every social-science role or activity.', '[]'::jsonb, '[]'::jsonb, ARRAY['unesco_definition', 'nuc_ccmas', 'openlearn_methodology', 'OPENLEARN_RESEARCH_QUESTION_IR']::text[], '[{"id":"unesco_definition","title":"Social science research","url":"https://www.unesco.org/en/query-list/s/social-science-research","region":null,"evidenceType":"item_definition_or_task_identity"},{"id":"nuc_ccmas","title":"Social Sciences CCMAS 2023","url":"https://www.nuc.edu.ng/wp-content/uploads/2026/03/Social-Sciences-CCMAS-FINAL-2023-A.pdf","region":null,"evidenceType":"D078_checkpoint_context_candidate"},{"id":"openlearn_methodology","title":"Defining your research methodology","url":"https://www.open.edu/openlearn/course/view.php?id=18286","region":null,"evidenceType":"independent_or_task_specific_explanation_candidate"},{"id":"OPENLEARN_RESEARCH_QUESTION_IR","title":"OpenLearn: Developing a research question in International Relations","url":"https://www.open.edu/openlearn/society-politics-law/developing-research-question-international-relations/?active-tab=content-tab","region":"global","evidenceType":"task_specific_learning_resource"}]'::jsonb, '[{"sourceId":"unesco_definition","title":"Social science research","url":"https://www.unesco.org/en/query-list/s/social-science-research","locator":"definition of systematic study and varied methods","claimRole":"item_identity"},{"sourceId":"nuc_ccmas","title":"Social Sciences CCMAS 2023","url":"https://www.nuc.edu.ng/wp-content/uploads/2026/03/Social-Sciences-CCMAS-FINAL-2023-A.pdf","locator":"printed p. 337: Nigerian course outcome proposal/data/report","claimRole":"checkpoint_fit"},{"sourceId":"openlearn_methodology","title":"Defining your research methodology","url":"https://www.open.edu/openlearn/course/view.php?id=18286","locator":"Sections connecting research questions, methodology, data collection and analysis; quantitative/qualitative distinction and mixed-method discussion.","claimRole":"plain_meaning"}]'::jsonb, 'global', '["Not every D078 job or activity conducts formal research.","The example is illustrative, not a factual claim about a specific Nigerian transport system.","ESRC is UK postgraduate guidance; NUC evidence is Nigeria-specific curriculum evidence.","Domain enrichment. Do not label this as taught by the Sociology programme unless a specific reviewed programme outcome supports that claim."]'::jsonb, 'source_supported_synthesis', 'medium', 'source_backed', 'linked', 'https://www.open.edu/openlearn/society-politics-law/developing-research-question-international-relations/?active-tab=content-tab', 'OpenLearn: Developing a research question in International Relations', '{"source_id":"OPENLEARN_RESEARCH_QUESTION_IR","title":"OpenLearn: Developing a research question in International Relations","publisher":null,"url":"https://www.open.edu/openlearn/society-politics-law/developing-research-question-international-relations/?active-tab=content-tab","locator":"Course sections: types of research questions; descriptive versus analytical questions; developing a good research question.","accessed_on":"2026-10-12","scope_limit":"International Relations examples and advanced level; the question-framing process transfers, but learners should adapt it to their own social-science topic."}'::jsonb, '2026-10-12', 'medium', '{"url":"https://www.open.edu/openlearn/society-politics-law/developing-research-question-international-relations/?active-tab=content-tab","locator":"Course sections: types of research questions; descriptive versus analytical questions; developing a good research question.","supports":"Task-specific learning resource for the item","access":"Free OpenLearn course; free account/sign-in required to enrol; 3 hours; advanced level."}'::jsonb, NULL, 'domain', '2026-10-12', 'approved', '{"claims":{"item_identity":{"source_references":[{"id":"unesco_definition","title":"Social science research","url":"https://www.unesco.org/en/query-list/s/social-science-research","region":null,"evidenceType":"item_definition_or_task_identity"}],"source_locators":[{"sourceId":"unesco_definition","title":"Social science research","url":"https://www.unesco.org/en/query-list/s/social-science-research","locator":"definition of systematic study and varied methods","claimRole":"item_identity"}]},"checkpoint_fit":{"source_references":[{"id":"nuc_ccmas","title":"Social Sciences CCMAS 2023","url":"https://www.nuc.edu.ng/wp-content/uploads/2026/03/Social-Sciences-CCMAS-FINAL-2023-A.pdf","region":null,"evidenceType":"D078_checkpoint_context_candidate"}],"source_locators":[{"sourceId":"nuc_ccmas","title":"Social Sciences CCMAS 2023","url":"https://www.nuc.edu.ng/wp-content/uploads/2026/03/Social-Sciences-CCMAS-FINAL-2023-A.pdf","locator":"printed p. 337: Nigerian course outcome proposal/data/report","claimRole":"checkpoint_fit"}]},"plain_meaning":{"source_references":[{"id":"openlearn_methodology","title":"Defining your research methodology","url":"https://www.open.edu/openlearn/course/view.php?id=18286","region":null,"evidenceType":"independent_or_task_specific_explanation_candidate"}],"source_locators":[{"sourceId":"openlearn_methodology","title":"Defining your research methodology","url":"https://www.open.edu/openlearn/course/view.php?id=18286","locator":"Sections connecting research questions, methodology, data collection and analysis; quantitative/qualitative distinction and mixed-method discussion.","claimRole":"plain_meaning"}]},"contextual_use":{"source_references":[{"id":"nuc_ccmas","title":"Social Sciences CCMAS 2023","url":"https://www.nuc.edu.ng/wp-content/uploads/2026/03/Social-Sciences-CCMAS-FINAL-2023-A.pdf","region":null,"evidenceType":"D078_checkpoint_context_candidate"}],"source_locators":[{"sourceId":"nuc_ccmas","title":"Social Sciences CCMAS 2023","url":"https://www.nuc.edu.ng/wp-content/uploads/2026/03/Social-Sciences-CCMAS-FINAL-2023-A.pdf","locator":"printed p. 337: Nigerian course outcome proposal/data/report","claimRole":"contextual_use"}]},"expected_output":{"source_references":[{"id":"nuc_ccmas","title":"Social Sciences CCMAS 2023","url":"https://www.nuc.edu.ng/wp-content/uploads/2026/03/Social-Sciences-CCMAS-FINAL-2023-A.pdf","region":null,"evidenceType":"D078_checkpoint_context_candidate"}],"source_locators":[{"sourceId":"nuc_ccmas","title":"Social Sciences CCMAS 2023","url":"https://www.nuc.edu.ng/wp-content/uploads/2026/03/Social-Sciences-CCMAS-FINAL-2023-A.pdf","locator":"printed p. 337: Nigerian course outcome proposal/data/report","claimRole":"contextual_use"}]}},"reviewed_by":"local_d078_item_disposition","decision_id":"d078-research-question-design"}'::jsonb, 'free_task_specific_learning_resource', NULL, 'English', 'Free OpenLearn course; free account/sign-in required to enrol; 3 hours; advanced level.', NULL, 'shared_foundation_candidate_for_research_routes', 'Shared foundation candidate for research routes', NULL, 'useful', 'A useful shared starting point when the learner chooses a research route; not a prerequisite for every social-science role or activity.'),
('domain', 'D078', 'D078', 'competency', 'd078-evaluate-evidence-and-limits', 'Evaluate evidence and explain what it can and cannot show', 'Evidence appraisal means checking who produced information, how it was gathered, whether it fits the question, and what conclusions are fair. A survey of one school, for example, cannot automatically describe every school.', 'Use this when reading a source, dataset or finding and deciding what conclusion it supports—and what it cannot support.', 'A brief source check and a conclusion that states a limitation; example is illustrative.', 'build_next', 'Useful where the learner reads evidence, supports a claim or advises on a decision; not a claim that every D078 role conducts formal research.', '[]'::jsonb, '[]'::jsonb, ARRAY['apsa_2024', 'openlearn_evidence', 'OPENLEARN_READING_EVIDENCE']::text[], '[{"id":"apsa_2024","title":"Rethinking Political Science Education: Presidential Task Force Report","url":"https://educate.apsanet.org/wp-content/uploads/APSA-Presidential-Task-Force-Report-on-Rethinking-Political-Science-Education-March-2024.pdf","region":null,"evidenceType":"item_definition_or_task_identity"},{"id":"openlearn_evidence","title":"EPQs: finding and using evidence","url":"https://www.open.edu/openlearn/course/view.php?id=17844","region":null,"evidenceType":"independent_or_task_specific_explanation_candidate"},{"id":"OPENLEARN_READING_EVIDENCE","title":"OpenLearn: Reading evidence in the social sciences","url":"https://www.open.edu/openlearn/society-politics-law/sociology/reading-evidence/content-section-0?intro=1","region":"global","evidenceType":"task_specific_learning_resource"}]'::jsonb, '[{"sourceId":"apsa_2024","title":"Rethinking Political Science Education: Presidential Task Force Report","url":"https://educate.apsanet.org/wp-content/uploads/APSA-Presidential-Task-Force-Report-on-Rethinking-Political-Science-Education-March-2024.pdf","locator":"printed p. 22: strengths/limits of methods and interpreting results","claimRole":"item_identity"},{"sourceId":"apsa_2024","title":"Rethinking Political Science Education: Presidential Task Force Report","url":"https://educate.apsanet.org/wp-content/uploads/APSA-Presidential-Task-Force-Report-on-Rethinking-Political-Science-Education-March-2024.pdf","locator":"printed p. 22: strengths/limits of methods and interpreting results","claimRole":"checkpoint_fit"},{"sourceId":"openlearn_evidence","title":"EPQs: finding and using evidence","url":"https://www.open.edu/openlearn/course/view.php?id=17844","locator":"Course material on finding, judging and using evidence, including source credibility and critical reading.","claimRole":"plain_meaning"}]'::jsonb, 'global', '["Introductory evidence checking is not a substitute for advanced systematic-review training.","Does not imply all D078 work has empirical data.","Domain enrichment. The Sociology programme connection does not mean the course teaches every listed research task."]'::jsonb, 'source_supported_synthesis', 'medium', 'source_backed', 'linked', 'https://www.open.edu/openlearn/society-politics-law/sociology/reading-evidence/content-section-0?intro=1', 'OpenLearn: Reading evidence in the social sciences', '{"source_id":"OPENLEARN_READING_EVIDENCE","title":"OpenLearn: Reading evidence in the social sciences","publisher":null,"url":"https://www.open.edu/openlearn/society-politics-law/sociology/reading-evidence/content-section-0?intro=1","locator":"Introduction and course summary: quantitative and qualitative evidence, method choices, interpretation, reliability, bias, limits and blind spots.","accessed_on":"2026-10-12","scope_limit":"Introductory Sociology course material; it teaches evidence appraisal concepts, not advanced systematic review or professional accreditation."}'::jsonb, '2026-10-12', 'medium', '{"url":"https://www.open.edu/openlearn/society-politics-law/sociology/reading-evidence/content-section-0?intro=1","locator":"Introduction and course summary: quantitative and qualitativ